247	// A read failure before any complete line yields no results and no failure
248	// count, but the stream error still reaches the caller.
249	func TestNormalizeIOReadErrorBeforeAnyLine(t *testing.T) {
250		src := &scriptReader{steps: []scriptStep{
251			{data: []byte(`{"timestamp":"cut off`), err: errSimulatedRead},
252		}}
253		var out bytes.Buffer
254		failures, err := NormalizeReader(src, &out)
255		if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
256			t.Fatalf("want ErrLogRead wrapping the cause, got %v", err)
257		}
258		if failures != 0 {
259			t.Fatalf("an unread stream has no failed logs, got %d", failures)
260		}
261		if out.Len() != 0 {
262			t.Fatalf("no complete line means no output, got %q", out.String())
263		}
264	}
265	
266	// The writer fails only when the final buffered batch is flushed at input
267	// end: the caller must still receive ErrLogWrite. When every log was valid
268	// the failure count stays zero; when invalid logs were already counted,
269	// that count must not be reset.
270	func TestNormalizeIOWriteErrorOnFinalFlush(t *testing.T) {
271		cases := []struct {
272			name         string
273			input        string
274			wantFailures int
275		}{
276			{
277				name:         "all logs valid",
278				input:        validLog("a") + "\n" + validLog("b") + "\n",
279				wantFailures: 0,
280			},
281			{
282				name: "invalid log already counted",
283				input: validLog("a") + "\n" +
284					`{"timestamp":"not-a-time","action":"b"}` + "\n" +
285					validLog("c") + "\n",
286				wantFailures: 1,
287			},
288		}
289		for _, tc := range cases {
290			t.Run(tc.name, func(t *testing.T) {
291				w := &failWriter{err: errSimulatedWrite} // reject every Write
292				failures, err := NormalizeReader(strings.NewReader(tc.input), w)
293				if !errors.Is(err, ErrLogWrite) || !errors.Is(err, errSimulatedWrite) {
294					t.Fatalf("want ErrLogWrite wrapping the cause, got %v", err)
295				}
296				if errors.Is(err, ErrLogRead) {
297					t.Fatalf("a healthy reader must not tag the error as a read failure: %v", err)
298				}
299				if !w.failed {
300					t.Fatalf("the final flush must actually have reached the failing writer")
301				}
302				if failures != tc.wantFailures {
303					t.Fatalf("write fault must not alter the failure count: got %d, want %d", failures, tc.wantFailures)
304				}
305			})
306		}
307	}
308	
309	// A write failure in the middle of processing (records larger than the
310	// internal buffer go straight to the underlying writer) stops the run with
311	// ErrLogWrite; whatever reached the writer may end mid-record, and the write
312	// fault never fabricates an ordinary log failure or moves the count.
313	func TestNormalizeIOWriteErrorMidStream(t *testing.T) {
314		t.Run("all valid logs", func(t *testing.T) {
315			line1 := bigValidLog("a")
316			line2 := bigValidLog("b")
317			encoded1 := encodedRecord(t, 1, line1)
318			if len(encoded1) <= 4096 {
319				t.Fatalf("test setup: encoded line must exceed the 4096-byte buffer, got %d", len(encoded1))
320			}
321			// Line 1 is accepted whole; the write for line 2 takes 120 bytes
322			// and then fails, leaving a truncated non-record tail.
323			w := &failWriter{allowBytes: len(encoded1), partial: 120, err: errSimulatedWrite}
324			failures, err := NormalizeReader(strings.NewReader(line1+"\n"+line2+"\n"), w)
325			if !errors.Is(err, ErrLogWrite) || !errors.Is(err, errSimulatedWrite) {
326				t.Fatalf("want ErrLogWrite wrapping the cause, got %v", err)
327			}
328			if failures != 0 {
329				t.Fatalf("write fault must not add a log failure, got %d", failures)
330			}
331			results := decodePrefix(t, w.buf.Bytes())
332			if len(results) != 1 || results[0]["ok"] != true {
333				t.Fatalf("only the fully written line 1 may decode whole: %#v", results)
334			}
335			if eventOf(t, results[0])["action"] != "a" {
336				t.Fatalf("written record must be the genuine first log")
337			}
338			if w.buf.Len() != len(encoded1)+120 {
339				t.Fatalf("the interrupted write must leave exactly 120 partial bytes beyond line 1, got total %d", w.buf.Len())
340			}
341		})
342	
343		t.Run("invalid log counted before the write fault", func(t *testing.T) {
344			line1 := bigValidLog("a")
345			encoded1 := encodedRecord(t, 1, line1)
346			invalid := `{"timestamp":"not-a-time","action":"b"}` // small failure result stays buffered
347			line3 := bigValidLog("c")
348			// Line 1 goes out whole; the next physical write (the buffered
349			// failure result, flushed while line 3 is encoded) accepts a few
350			// bytes and then fails.
351			w := &failWriter{allowBytes: len(encoded1) + 5, err: errSimulatedWrite}
352			failures, err := NormalizeReader(strings.NewReader(line1+"\n"+invalid+"\n"+line3+"\n"), w)
353			if !errors.Is(err, ErrLogWrite) {
354				t.Fatalf("want ErrLogWrite, got %v", err)
355			}
356			if failures != 1 {
357				t.Fatalf("the invalid log must still count exactly once after the write fault, got %d", failures)
358			}
359			results := decodePrefix(t, w.buf.Bytes())
360			if len(results) != 1 || results[0]["ok"] != true {
361				t.Fatalf("only line 1 should have left a whole record: %#v", results)
362			}
363		})
364	}
365	
366	// If the reader has already failed and flushing the buffered results fails
367	// too, the caller must still receive the original read cause: the later
368	// write error must not mask it.
369	func TestNormalizeIOReadErrorWinsOverFlushError(t *testing.T) {
370		complete := validLog("a") + "\n" +
371			`{"timestamp":"not-a-time","action":"b"}` + "\n" +
372			validLog("c") + "\n"
373		src := &scriptReader{steps: []scriptStep{
374			{data: []byte(complete)},
375			{data: []byte(`{"truncated":`), err: errSimulatedRead},
376		}}
377		// Small records stay in the internal buffer, so the first physical
378		// write is the shutdown flush, which fails with a distinct error.
379		w := &failWriter{err: errSimulatedWrite}
